class Konto {
  #saldo; // prywatne pole - musi byc zadeklarowane w ciele klasy

  constructor(saldoPoczatkowe) {
    this.#saldo = saldoPoczatkowe;
  }

  wplac(kwota) {
    this.#saldo += kwota;
    return this.#saldo;
  }

  get saldo() {
    return this.#saldo; // publiczny getter jako "okno" do prywatnego pola
  }
}

const konto = new Konto(100);
konto.wplac(50);
