class Sejf {
  #kod;
  constructor(kod) {
    this.#kod = kod;
  }
  otworz(proba) {
    return proba === this.#kod;
  }
}

const sejf = new Sejf("1234");
console.log(sejf.otworz("1234")); // true
console.log(sejf.otworz("0000")); // false

class LicznikOdwiedzin {
  #odwiedziny = 0;
  zwieksz() {
    this.#odwiedziny++;
  }
  get pobierz() {
    return this.#odwiedziny;
  }
}

const licznik = new LicznikOdwiedzin();
for (let i = 0; i < 5; i++) {
  licznik.zwieksz();
}
console.log(licznik.pobierz); // 5

class Karta {
  #numer;
  constructor(numer) {
    this.#numer = numer;
  }
  #maskuj() {
    const ostatnie4 = this.#numer.slice(-4);
    return "*".repeat(this.#numer.length - 4) + ostatnie4;
  }
  pokaz() {
    return this.#maskuj();
  }
}

const karta = new Karta("1234567812345678");
console.log(karta.pokaz()); // "************5678"

