class Haslo {
  #wartosc;
  constructor(wartosc) {
    this.#wartosc = wartosc;
  }
  sprawdz(proba) {
    return proba === this.#wartosc;
  }
  zmien(stara, nowa) {
    if (this.sprawdz(stara)) {
      this.#wartosc = nowa;
      return true;
    }
    return false;
  }
}

const haslo = new Haslo("tajne123");
console.log(haslo.zmien("zle", "nowe"));     // false - stare haslo nieprawidlowe
console.log(haslo.zmien("tajne123", "nowe")); // true - zmienione poprawnie
console.log(haslo.sprawdz("nowe"));           // true

class Magazyn {
  #stan = {};
  dodaj(nazwa, ilosc) {
    this.#stan[nazwa] = (this.#stan[nazwa] || 0) + ilosc;
  }
  pobierzIlosc(nazwa) {
    return this.#stan[nazwa] || 0;
  }
}

const magazyn = new Magazyn();
magazyn.dodaj("sruby", 100);
magazyn.dodaj("sruby", 50);
console.log(magazyn.pobierzIlosc("sruby")); // 150
console.log(magazyn.pobierzIlosc("gwozdzie")); // 0

class Generator {
  #losujLiczbe() {
    return Math.floor(Math.random() * 100) + 1;
  }
  generuj(ile) {
    return Array.from({ length: ile }, () => this.#losujLiczbe());
  }
}

const generator = new Generator();
const liczby = generator.generuj(5);
console.log(liczby.length); // 5
console.log(liczby.every((n) => n >= 1 && n <= 100)); // true

